package com.nook.controller; import com.nook.dto.ApiDtos.*; import com.nook.security.CurrentUser; import com.nook.service.DiscoveryService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1") public class DiscoveryController {final DiscoveryService s;public DiscoveryController(DiscoveryService s){this.s=s;}@GetMapping("/discover") PageDto<DiscoverProfile> discover(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return s.discover(CurrentUser.id(),page,Math.min(size,50));}@PostMapping("/coffee-likes/{id}") LikeResult like(@PathVariable UUID id){return s.like(CurrentUser.id(),id);}@DeleteMapping("/coffee-likes/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void pass(@PathVariable UUID id){s.pass(CurrentUser.id(),id);}@GetMapping("/matches") List<MatchDto> matches(){return s.matches(CurrentUser.id());}@DeleteMapping("/matches/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID id){s.deleteMatch(CurrentUser.id(),id);}}
